class StringReverser:
    def __init__(self, original_string):
        self.original_string = original_string
        self.reversed_chars = []
        self.current_index = 0

    def process_characters(self):
        self.current_index = len(self.original_string) - 1
        while self.current_index >= 0:
            self.reversed_chars.append(self.original_string[self.current_index])
            self.current_index -= 1
        return self.reversed_chars

class StringJoiner:
    def __init__(self, char_list):
        self.char_list = char_list
        self.result_string = ""
        self.separator = ""

    def join(self):
        self.result_string = self.separator.join(self.char_list)
        return self.result_string

class ReverseString:
    def __init__(self):
        self.input_string = ""
        self.reverser_instance = None
        self.joiner_instance = None
        self.final_reversed_string = ""

    def reverse(self, s):
        self.input_string = s
        self.reverser_instance = StringReverser(self.input_string)
        processed_chars = self.reverser_instance.process_characters()
        self.joiner_instance = StringJoiner(processed_chars)
        self.final_reversed_string = self.joiner_instance.join()
        return self.final_reversed_string

def reverse_string(s):
    reverser = ReverseString()
    return reverser.reverse(s)

