class FactorialCalculator:
    def __init__(self):
        self.memo = {0: 1}

    def compute(self, n):
        if not isinstance(n, int) or n < 0:
            raise ValueError("Input must be a non-negative integer.")
        if n in self.memo:
            return self.memo[n]
        self.memo[n] = n * self.compute(n - 1)
        return self.memo[n]

class InputValidator:
    def __init__(self):
        self.min_value = 0
        self.error_message = "Input must be a non-negative integer."

    def validate(self, n):
        if not isinstance(n, int) or n < self.min_value:
            raise ValueError(self.error_message)
        self.last_validated_input = n
        return True

class FactorialSolver:
    def __init__(self):
        self.calculator = FactorialCalculator()
        self.validator = InputValidator()
        self.history = []

    def solve(self, n):
        self.validator.validate(n)
        result = self.calculator.compute(n)
        self.history.append((n, result))
        return result

def calculate_factorial(n):
    solver = FactorialSolver()
    return solver.solve(n)

