    def sanitize(self, text):
        self.text_input = text
        self.cleaned_chars = [char.lower() for char in self.text_input if char.isalnum()]
        self.cleaned_string = "".join(self.cleaned_chars)
        return self.cleaned_string

class PalindromeChecker:
    def __init__(self):
        self.sanitizer = Sanitizer()

    def check(self, cleaned_text):
        self.input_text = cleaned_text
        self.reversed_text = self.input_text[::-1]
        self.is_it_palindrome = (self.input_text == self.reversed_text)
        return self.is_it_palindrome

class PalindromeService:
    def __init__(self):
        self.checker = PalindromeChecker()

    def is_palindrome(self, text):
        self.original_text = text
        self.sanitized_text = self.checker.sanitizer.sanitize(self.original_text)
        self.result = self.checker.check(self.sanitized_text)
        return self.result

def is_palindrome(text):
    service = PalindromeService()
    return service.is_palindrome(text)

