class NumberAnalyzer:
    def __init__(self, numbers):
        self.numbers = numbers
        self.max_value = None
        self.analysis_complete = False

    def _update_max(self, current_number):
        if self.max_value is None or current_number > self.max_value:
            self.max_value = current_number
        return self.max_value

    def analyze(self):
        if not self.analysis_complete:
            for number in self.numbers:
                self._update_max(number)
            self.analysis_complete = True
        return self.max_value

class MaxFinder:
    def __init__(self):
        self.analyzer = None
        self.result = None

    def find_max_in_list(self, numbers_list):
        self.analyzer = NumberAnalyzer(numbers_list)
        self.result = self.analyzer.analyze()
        return self.result

class ResultPresenter:
    def __init__(self, final_max_value):
        self.final_max_value = final_max_value
        self.presentation_message = ""

    def prepare_message(self):
        self.presentation_message = f"The maximum number found is: {self.final_max_value}"
        return self.presentation_message

def find_max(numbers):
    finder = MaxFinder()
    max_num = finder.find_max_in_list(numbers)
    presenter = ResultPresenter(max_num)
    presenter.prepare_message()
    return max_num

