class TextProcessor:
    def __init__(self, text):
        self.original_text = text
        self.processed_words = []

    def clean_text(self):
        self.cleaned_text = ''.join(char.lower() if char.isalpha() or char.isspace() else ' ' for char in self.original_text)
        return self.cleaned_text

    def tokenize_words(self):
        cleaned = self.clean_text()
        self.processed_words = [word for word in cleaned.split() if word]
        return self.processed_words

class FrequencyCounter:
    def __init__(self, words):
        self.word_list = words
        self.frequency_map = {}

    def calculate_frequencies(self):
        for word in self.word_list:
            self.frequency_map[word] = self.frequency_map.get(word, 0) + 1
        return self.frequency_map

class WordAnalyzer:
    def __init__(self, text):
        self.input_text = text
        self.final_frequencies = {}

    def analyze(self):
        processor = TextProcessor(self.input_text)
        tokenized = processor.tokenize_words()
        counter = FrequencyCounter(tokenized)
        self.final_frequencies = counter.calculate_frequencies()
        return self.final_frequencies

def word_frequency(text):
    analyzer = WordAnalyzer(text)
    return analyzer.analyze()

