class ListProcessor:
    def __init__(self, data_list):
        self.data_list = data_list
        self.sum_val = 0
        self.count_val = 0

    def process_list(self):
        for item in self.data_list:
            self.sum_val += item
            self.count_val += 1
        return self.sum_val, self.count_val

class AverageCalculator:
    def __init__(self, processor):
        self.processor = processor
        self.computed_average = 0.0

    def calculate(self):
        total_sum, total_count = self.processor.process_list()
        if total_count == 0:
            self.computed_average = 0.0
        else:
            self.computed_average = float(total_sum) / total_count
        return self.computed_average

class ResultFormatter:
    def __init__(self, calculator):
        self.calculator = calculator
        self.formatted_result = ""

    def format_output(self):
        self.formatted_result = str(self.calculator.calculate())
        return self.formatted_result

def calculate_average(numbers):
    processor = ListProcessor(numbers)
    calculator = AverageCalculator(processor)
    formatter = ResultFormatter(calculator)
    return float(formatter.format_output())

