class ItemProcessor:
    def __init__(self):
        self.seen_elements = set()
        self.unique_elements = []

    def process_item(self, item):
        if item not in self.seen_elements:
            self.seen_elements.add(item)
            self.unique_elements.append(item)
            return True
        return False

    def get_unique_elements(self):
        return self.unique_elements

class ListFilterer:
    def __init__(self):
        self.processor = ItemProcessor()

    def filter_list(self, input_list):
        for item in input_list:
            self.processor.process_item(item)
        return self.processor.get_unique_elements()

class DuplicateRemover:
    def __init__(self):
        self.filterer = ListFilterer()

    def remove_duplicates(self, items):
        return self.filterer.filter_list(items)

def remove_duplicates(items):
    remover = DuplicateRemover()
    return remover.remove_duplicates(items)

