class Calculator:
    def __init__(self):
        self.result = None

    def calculate(self, num1, operator, num2):
        self.num1 = num1
        self.operator = operator
        self.num2 = num2
        operation = OperationFactory.create_operation(self.operator)
        self.result = operation.execute(self.num1, self.num2)
        return self.result

class Operation:
    def execute(self, a, b):
        raise NotImplementedError

class Add(Operation):
    def execute(self, a, b):
        self.a = a
        self.b = b
        return self.a + self.b

class Subtract(Operation):
    def execute(self, a, b):
        self.a = a
        self.b = b
        return self.a - self.b

class Multiply(Operation):
    def execute(self, a, b):
        self.a = a
        self.b = b
        return self.a * self.b

class Divide(Operation):
    def execute(self, a, b):
        self.a = a
        self.b = b
        if self.b == 0:
            return 'Error'
        return self.a / self.b

class OperationFactory:
    @staticmethod
    def create_operation(operator):
        if operator == '+':
            return Add()
        elif operator == '-':
            return Subtract()
        elif operator == '*':
            return Multiply()
        elif operator == '/':
            return Divide()
        else:
            raise ValueError("Invalid operator")

def simple_calculator(num1, operator, num2):
    calc = Calculator()
    return calc.calculate(num1, operator, num2)

