import math

class NumberChecker:
    def __init__(self, number):
        self.number = number
        self.is_greater_than_one = False
        self.divisors = []

    def check_greater_than_one(self):
        self.is_greater_than_one = self.number > 1
        return self.is_greater_than_one

    def find_divisors(self):
        self.divisors = []
        for i in range(2, int(math.sqrt(self.number)) + 1):
            if self.number % i == 0:
