class FibonacciGenerator:
    def __init__(self):
        self.sequence = []

    def generate(self, n):
        self.n = n
        self.result_builder = FibonacciResultBuilder()
        self.result_builder.initialize_sequence(self.n)
        return self.result_builder.build_sequence()

class FibonacciResultBuilder:
    def __init__(self):
        self.current_sequence = []

    def initialize_sequence(self, count):
        self.count = count
        if self.count >= 1:
            self.current_sequence.append(0)
        if self.count >= 2:
            self.current_sequence.append(1)

    def build_sequence(self):
        self.index_manager = IndexManager(self.count)
        while self.index_manager.has_next():
            self.next_index = self.index_manager.get_next_index()
            self.next_value = self.current_sequence[self.next_index - 1] + self.current_sequence[self.next_index - 2]
            self.current_sequence.append(self.next_value)
        return self.current_sequence

class IndexManager:
    def __init__(self, limit):
        self.limit = limit
        self.current_index = 2

    def has_next(self):
        return self.current_index < self.limit

    def get_next_index(self):
        self.prev_index = self.current_index
        self.current_index += 1
        return self.prev_index

def fibonacci_sequence(n):
    generator = FibonacciGenerator()
    return generator.generate(n)

