class Alphabet:
    def __init__(self):
        self.lowercase_start = ord('a')
        self.uppercase_start = ord('A')
        self.alphabet_size = 26

    def is_lowercase(self, char_code):
        return self.lowercase_start <= char_code < self.lowercase_start + self.alphabet_size

    def is_uppercase(self, char_code):
        return self.uppercase_start <= char_code < self.uppercase_start + self.alphabet_size

    def get_base(self, is_upper):
        if is_upper:
            return self.uppercase_start
        else:
            return self.lowercase_start

class Cipher:
    def __init__(self, alphabet_obj):
        self.alphabet = alphabet_obj

    def encrypt_char(self, char, shift):
        char_code = ord(char)
        if self.alphabet.is_lowercase(char_code):
            base = self.alphabet.get_base(False)
            return chr(base + (char_code - base + shift) % self.alphabet.alphabet_size)
        elif self.alphabet.is_uppercase(char_code):
            base = self.alphabet.get_base(True)
            return chr(base + (char_code - base + shift) % self.alphabet.alphabet_size)
        else:
            return char

class CaesarCipher:
    def __init__(self, shift):
        self.alphabet = Alphabet()
        self.cipher_engine = Cipher(self.alphabet)
        self.shift_value = shift

    def encrypt(self, text):
        encrypted_chars = []
        for char in text:
            encrypted_chars.append(self.cipher_engine.encrypt_char(char, self.shift_value))
        return "".join(encrypted_chars)

def caesar_cipher_encrypt(text, shift):
    cipher_instance = CaesarCipher(shift)
    return cipher_instance.encrypt(text)

