class NumberOperations:
    def __init__(self, numbers):
        self.numbers = numbers
        self.product_calculator = ProductCalculator(self.numbers)
        self.root_calculator = RootCalculator()

    def get_numbers(self):
        return self.numbers

    def calculate_geometric_mean(self):
        if not self.numbers:
            raise ValueError("The list of numbers cannot be empty.")
        for num in self.numbers:
            if not isinstance(num, (int, float)) or num <= 0:
                raise ValueError("All numbers must be positive.")

        product = self.product_calculator.calculate_product()
        n = self.get_length()
        return self.root_calculator.n_th_root(product, n)

    def get_length(self):
        return len(self.numbers)

class ProductCalculator:
    def __init__(self, numbers):
        self.numbers = numbers

    def calculate_product(self):
        self.product = 1.0
        for num in self.numbers:
            self.product *= float(num)
        return self.product

class RootCalculator:
    def n_th_root(self, value, n):
        if n <= 0:
            raise ValueError("The root degree must be positive.")
        self.result = value**(1/float(n))
        return self.result

def geometric_mean(numbers):
    operations = NumberOperations(numbers)
    return operations.calculate_geometric_mean()

