        for num in this.numbers:
            if not isinstance(num, (int, float)) or num <= 0:
                raise ValueError("All numbers must be positive.")

        product = this.product_calculator.calculate_product()
        n = this.get_length()
        return this.root_calculator.n_th_root(product, n)

