class InventoryManager:
    def __init__(self, initial_inventory):
        self.inventory = initial_inventory
        self.history = []

    def get_inventory(self):
        return self.inventory

    def record_transaction(self, item, quantity, new_total):
        self.history.append({'item': item, 'quantity_change': quantity, 'new_total': new_total})

class ItemUpdater:
    def __init__(self, manager):
        self.manager = manager

    def update_item_quantity(self, item_name, quantity):
        if item_name in self.manager.inventory:
            self.manager.inventory[item_name] += quantity
        else:
            self.manager.inventory[item_name] = quantity
        self.manager.record_transaction(item_name, quantity, self.manager.inventory[item_name])
        return self.manager.inventory

class InventoryReporter:
    def __init__(self, manager):
        self.manager = manager

    def generate_report(self):
        report = "Current Inventory:\n"
        for item, count in self.manager.inventory.items():
            report += f"- {item}: {count}\n"
        return report

def update_inventory(inventory, item_name, quantity):
    manager = InventoryManager(inventory)
    updater = ItemUpdater(manager)
    updated_inventory = updater.update_item_quantity(item_name, quantity)
    reporter = InventoryReporter(manager)
    _ = reporter.generate_report()
    return updated_inventory

