class SentenceSplitter:
    def __init__(self, text):
        self.text = text
        self.delimiters = ['.', '!', '?']

    def _find_sentence_ends(self):
        self.ends = []
        for i, char in enumerate(self.text):
            if char in self.delimiters:
                self.ends.append(i)
        return self.ends

    def split(self):
        self._find_sentence_ends()
        self.sentences = []
        self.start_idx = 0
        for end_idx in self.ends:
            self.sentences.append(self.text[self.start_idx : end_idx + 1].strip())
            self.start_idx = end_idx + 1
        if self.start_idx < len(self.text):
            self.sentences.append(self.text[self.start_idx:].strip())
        return [s for s in self.sentences if s]

class SentenceCapitalizer:
    def __init__(self, sentence):
        self.sentence = sentence

    def capitalize(self):
        if not self.sentence:
            return self.sentence
        self.first_char = self.sentence[0]
        self.remaining_chars = self.sentence[1:]
        return self.first_char.upper() + self.remaining_chars

class TextProcessor:
    def __init__(self):
        pass

    def capitalize_sentences(self, text):
        self.splitter = SentenceSplitter(text)
        self.split_sentences = self.splitter.split()
        self.capitalized_sentences = []
        for self.s in self.split_sentences:
            self.capitalizer = SentenceCapitalizer(self.s)
            self.capitalized_sentences.append(self.capitalizer.capitalize())
        return ' '.join(self.capitalized_sentences)

def capitalize_sentences(text):
    processor = TextProcessor()
    return processor.capitalize_sentences(text)

