class Squarer:
    def __init__(self):
        self.value = 0

    def set_value(self, num):
        self.value = num
        return self

    def get_square(self):
        return self.value * self.value

class NumberGenerator:
    def __init__(self, limit):
        self.limit = limit
        self.current = 0

    def has_next(self):
        return self.current < self.limit

    def next_number(self):
        self.current += 1
        return self.current

class ListCreator:
    def __init__(self):
        self.result_list = []

    def add_to_list(self, item):
        self.result_list.append(item)
        return self

    def get_list(self):
        return self.result_list

def list_of_squares(n):
    creator = ListCreator()
    if n <= 0:
        return creator.get_list()

    generator = NumberGenerator(n)
    squarer = Squarer()

    while generator.has_next():
        num = generator.next_number()
        squarer.set_value(num)
