        return this.result_list

def list_of_squares(n):
    creator = ListCreator()
    if n <= 0:
        return creator.get_list()

    generator = NumberGenerator(n)
    squarer = Squarer()

    while generator.has_next():
        num = generator.next_number()
        squarer.set_value(num)
        square = squarer.get_square()
        creator.add_to_list(square)
    return creator.get_list()

