class CharCounter:
    def __init__(self):
        self.counts = {}

    def process_char(self, char):
        char_lower = char.lower()
        if char_lower.isalpha():
            self.counts[char_lower] = self.counts.get(char_lower, 0) + 1

    def get_counts(self):
        return self.counts

class TextProcessor:
    def __init__(self, text):
        self.original_text = text
        self.char_counter = CharCounter()

    def analyze_text(self):
        for char in self.original_text:
            if char != ' ':
                self.char_counter.process_char(char)
        return self.char_counter.get_counts()

class ResultFinder:
    def __init__(self, char_counts, original_text):
        self.char_counts = char_counts
        self.original_text = original_text
        self.max_count = 0
        self.most_frequent = None

    def find_most_frequent(self):
        for char in self.original_text.lower():
            if char.isalpha() and char in self.char_counts:
                current_count = self.char_counts[char]
                if current_count > self.max_count:
                    self.max_count = current_count
                    self.most_frequent = char
        return self.most_frequent

def most_frequent_char(text):
    processor = TextProcessor(text)
    counts = processor.analyze_text()
    finder = ResultFinder(counts, text)
    return finder.find_most_frequent()

