class DigitExtractor:
    def __init__(self, number):
        self.number = number
        self.digits = []

    def extract_all(self):
        temp_num = self.number
        while temp_num > 0:
            self.digits.append(temp_num % 10)
            temp_num //= 10
        self.digits.reverse()
        return self.digits

class DigitSummer:
    def __init__(self, digits_list):
        self.digits_list = digits_list
        self.total_sum = 0

    def calculate_sum(self):
        for digit in self.digits_list:
            self.total_sum += digit
        return self.total_sum

class NumberProcessor:
    def __init__(self, n):
        self.n = n

    def sum_digits(self):
        if self.n < 0:
            raise ValueError("Input must be a non-negative integer.")
        if self.n == 0:
            return 0
        extractor = DigitExtractor(self.n)
        extracted_digits = extractor.extract_all()
        summer = DigitSummer(extracted_digits)
        final_sum = summer.calculate_sum()
        return final_sum

def sum_digits(n):
    processor = NumberProcessor(n)
    return processor.sum_digits()

