class GameChoice:
    def __init__(self, name):
        self.name = name

    def beats(self, other_choice):
        if self.name == 'rock' and other_choice.name == 'scissors':
            return True
        if self.name == 'paper' and other_choice.name == 'rock':
            return True
        if self.name == 'scissors' and other_choice.name == 'paper':
            return True
        return False

class Player:
    def __init__(self, name, choice_str):
        self.name = name
        self.choice = GameChoice(choice_str)

    def get_choice(self):
        return self.choice

class GameRound:
    def __init__(self, player1, player2):
        self.player1 = player1
        self.player2 = player2

    def determine_winner(self):
        choice1 = self.player1.get_choice()
        choice2 = self.player2.get_choice()

        if choice1.name == choice2.name:
            return "It's a tie!"
        elif choice1.beats(choice2):
            return "Player 1 wins!"
        else:
            return "Player 2 wins!"

def rock_paper_scissors(player1_choice, player2_choice):
    player1 = Player("Player 1", player1_choice)
    player2 = Player("Player 2", player2_choice)
    game_round = GameRound(player1, player2)
    return game_round.determine_winner()

