class MatrixOperations:
    def __init__(self):
        self.result_matrix_rows = 0
        self.result_matrix_cols = 0
        self.current_sum = 0

    def add_elements(self, element1, element2):
        self.current_sum = element1 + element2
        return self.current_sum

class MatrixProcessor:
    def __init__(self):
        self.current_row_result = []
        self.all_rows_result = []
        self.row_index = 0
        self.col_index = 0
        self.matrix_ops = MatrixOperations()

    def process_row(self, row1, row2):
        self.current_row_result = []
        self.col_index = 0
        for element1, element2 in zip(row1, row2):
            self.current_row_result.append(self.matrix_ops.add_elements(element1, element2))
            self.col_index += 1
        return self.current_row_result

class MatrixAdder:
    def __init__(self):
        self.final_result = []
        self.processor = MatrixProcessor()
        self.matrix1_rows = 0
        self.matrix2_rows = 0
        self.matrix1_cols = 0
        self.matrix2_cols = 0

    def add(self, matrix1, matrix2):
        self.final_result = []
        self.matrix1_rows = len(matrix1)
        self.matrix2_rows = len(matrix2)
        if self.matrix1_rows > 0:
            self.matrix1_cols = len(matrix1[0])
        if self.matrix2_rows > 0:
            self.matrix2_cols = len(matrix2[0])
        self.processor.row_index = 0
        for row1, row2 in zip(matrix1, matrix2):
