class Portfolio:
    def __init__(self, stocks_dict, prices_dict):
        self.stocks = [Stock(t, q) for t, q in stocks_dict.items()]
        self.prices = {p.get_ticker(): p.get_price() for p in [PriceData(t, pr) for t, pr in prices_dict.items()]}

    def calculate_value(self):
        total_value = 0
        for stock_obj in self.stocks:
            ticker = stock_obj.get_ticker()
            quantity = stock_obj.get_quantity()
            if ticker in self.prices:
                price = self.prices[ticker]
                self_stock_value = quantity * price
                total_value += self_stock_value
        return total_value

def portfolio_value(stocks, prices):
    self_portfolio = Portfolio(stocks, prices)
    return self_portfolio.calculate_value()

