        sorted_unique = sorter.get_sorted_unique()
        finder = LargestFinder(sorted_unique)
        return finder.find_second_largest_value()

def find_second_largest(numbers):
    calculator = SecondLargestCalculator(numbers)
    return calculator.calculate_second_largest()

