class RunLengthEncoder:
    def __init__(self):
        self.encoded_string = ""

    def encode(self, s):
        if not s:
            return ""
        self.current_char = s[0]
        self.current_count = 0

        for char in s:
            self.process_char(char)
        self.append_current_run()
        return self.encoded_string

    def process_char(self, char):
        if char == self.current_char:
            self.current_count += 1
        else:
            self.append_current_run()
            self.current_char = char
            self.current_count = 1

    def append_current_run(self):
        self.encoded_string += self.current_char + str(self.current_count)

class EncoderFactory:
    def create_encoder(self):
        return RunLengthEncoder()

class EncodingService:
    def __init__(self):
        self.factory = EncoderFactory()

    def perform_encoding(self, input_string):
        self.encoder = self.factory.create_encoder()
        self.result = self.encoder.encode(input_string)
        return self.result

def run_length_encode(s):
