class BinaryDigit:
    def __init__(self, value):
        self.value = int(value)
        self.power = 0
        self.decimal_value = 0

    def set_power(self, power):
        self.power = power
        self.calculate_decimal()

    def calculate_decimal(self):
        self.decimal_value = self.value * (2 ** self.power)

    def get_decimal_value(self):
        return self.decimal_value

class BinaryNumber:
    def __init__(self, binary_string):
        self.binary_string = binary_string
        self.digits = []
        self.process_digits()
        self.total_decimal = 0

    def process_digits(self):
        for i, digit_char in enumerate(reversed(self.binary_string)):
            digit = BinaryDigit(digit_char)
            digit.set_power(i)
            self.digits.append(digit)

    def calculate_total_decimal(self):
        self.total_decimal = sum(digit.get_decimal_value() for digit in self.digits)
        return self.total_decimal

class BinaryConverter:
    def __init__(self):
        self.last_converted_string = None
        self.last_converted_decimal = None

    def convert(self, binary_string):
        self.last_converted_string = binary_string
        binary_num = BinaryNumber(binary_string)
        self.last_converted_decimal = binary_num.calculate_total_decimal()
        return self.last_converted_decimal

def binary_to_decimal(binary_string):
    converter = BinaryConverter()
    result = converter.convert(binary_string)
    return result

